-- Test seed: a small, hand-shaped corpus with known answers (h-index, lineage depth, topic paths,
-- retraction exposure). Loaded into the test database by `pnpm db:test`. Explicit ids keep tests stable.
-- Generated by scripts/dev/gen-test-seed.py.
BEGIN;
-- Users: the hash strings are well-formed Argon2id placeholders; tests never log in with them.
-- One real-looking retraction: paper 22 is cited by 24, which is cited by 27 (two-hop exposure).
SELECT setval(pg_get_serial_sequence('institution', 'institution_id'), (SELECT max(institution_id) FROM institution));
SELECT setval(pg_get_serial_sequence('venue', 'venue_id'), (SELECT max(venue_id) FROM venue));
SELECT setval(pg_get_serial_sequence('author', 'author_id'), (SELECT max(author_id) FROM author));
SELECT setval(pg_get_serial_sequence('topic', 'topic_id'), (SELECT max(topic_id) FROM topic));
SELECT setval(pg_get_serial_sequence('paper', 'paper_id'), (SELECT max(paper_id) FROM paper));
SELECT setval(pg_get_serial_sequence('method', 'method_id'), (SELECT max(method_id) FROM method));
SELECT setval(pg_get_serial_sequence('dataset', 'dataset_id'), (SELECT max(dataset_id) FROM dataset));
SELECT setval(pg_get_serial_sequence('user_account', 'user_id'), (SELECT max(user_id) FROM user_account));
SELECT setval(pg_get_serial_sequence('collection', 'collection_id'), (SELECT max(collection_id) FROM collection));
SELECT setval(pg_get_serial_sequence('note', 'note_id'), (SELECT max(note_id) FROM note));
COMMIT;
